<?php $title='Editar módulo'; ?><section class="page-head"><div><h1>Editar <?= e($project['name']) ?></h1><p>Configure o cadastro estrutural do módulo.</p></div></section><form class="panel form-grid" method="post" action="<?= e(base_url('projetos/'.$project['id'])) ?>" data-loading><?= csrf_field() ?><label>Nome comercial *<input name="name" value="<?= e($project['name']) ?>" required></label><label>Nome completo<input name="full_name" value="<?= e($project['full_name']) ?>"></label><label>Identificador<input value="<?= e($project['code']) ?>" disabled></label><label>Versão *<input name="version" value="<?= e($project['version']) ?>" required></label><label>URL pública<input type="url" name="url" value="<?= e($project['url']) ?>"></label><label>URL administrativa<input type="url" name="admin_url" value="<?= e($project['admin_url']) ?>"></label><label>Categoria<input name="category" value="<?= e($project['category']) ?>"></label><label>Ícone<input name="icon" value="<?= e($project['icon']) ?>"></label><label>Ordem<input type="number" name="display_order" value="<?= (int)$project['display_order'] ?>"></label><label>Status<select name="status"><option value="deploying" <?= $project['status']==='deploying'?'selected':'' ?>>Em implantação</option><option value="active" <?= $project['status']==='active'?'selected':'' ?>>Ativo</option><option value="inactive" <?= $project['status']==='inactive'?'selected':'' ?>>Inativo</option></select></label><label class="full">Descrição<textarea name="description" rows="5"><?= e($project['description']) ?></textarea></label><div class="form-actions full"><a class="btn" href="<?= e(base_url('projetos/'.$project['id'])) ?>">Cancelar</a><button class="btn primary">Salvar módulo</button></div></form>
